// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    function setUp() public { c = new RoundFactory(); }
    function testRegression_property() public {
        address operator = address(0x123);
        vm.prank(address(this));
        c.initialize();
        vm.prank(address(this));
        c.updateAlloSettings(address(0x456));
        vm.prank(address(this));
        c.updateRoundImplementation(payable(address(0x789)));
        address testAddr = address(0x456);
        vm.prank(address(this));
        c.updateAlloSettings(testAddr);
        address stored = c.alloSettings();
        assertTrue(stored == testAddr, "alloSettings should be the value set");
    }
}
